(ns fastmath.random.fitting-test
  (:require [fastmath.random.fitting :as sut]
            [fastmath.random :as r]
            [fastmath.random.distributions :as distr]
            [fastmath.random.fit-specs :as fit-specs]
            [fastmath.core :as m]
            [fastmath.stats :as stats]
            [clojure.edn :as edn]
            [clojure.java.io :as io]
            [clojure.test :as t]))

;; reference: R fitdistrplus::fitdist(method = "mle") and gofstat, generated by
;; utils/fastmath/dev/generate_fit_mle_reference.R
(def ^:private mle-reference
  (delay (edn/read-string (slurp (io/resource "random/fit_mle_reference.edn")))))

(defn- rel-error
  ^double [^double a ^double b]
  (m// (m/abs (m/- a b)) (m/max (m/abs b) 1.0e-300)))

(defn- close?
  [a b ^double tolerance]
  (m/<= (rel-error a b) tolerance))

;; a family which is a normal distribution with an extra integer parameter, only to test the engine:
;; a specification without estimators and with an :integer role parameter
(def ^:private hook-calls (atom {:moments 0 :lmoments 0}))

(def ^:private int-normal-fit-spec
  {:params [{:name :mu :domain :real :role :location}
            {:name :sd :domain :positive :role :scale}
            {:name :k :domain :positive :role :integer}]
   :valid? #(fit-specs/real-data-error % 2)
   ;; theoretical moments and L-moments of the normal distribution, counted to see that they are used
   :moments (fn [{:keys [mu sd]}] (swap! hook-calls update :moments inc) [mu (+ (* mu mu) (* sd sd))])
   :lmoments (fn [{:keys [sd]} ] (swap! hook-calls update :lmoments inc) [0.0 (/ sd (Math/sqrt Math/PI))])})

;; registered only while the tests of this namespace run: other test namespaces enumerate the keys of `r/distribution`
(defn- int-normal
  ([_] (int-normal :fit-test-int-normal nil))
  ([_ {:keys [mu sd] :or {mu 0.0 sd 1.0}}]
   (let [d (r/normal {:mu mu :sd sd})]
     (distr/->distribution {:pdf (fn ^double [^double x] (r/pdf d x))
                            :lpdf (fn ^double [^double x] (r/lpdf d x))
                            :cdf (fn ^double [^double x] (r/cdf d x))
                            :icdf (fn ^double [^double p] (r/icdf d p))
                            :continuous? true
                            :name :fit-test-int-normal
                            :parameters [:mu :sd :k]
                            :lower-bound ##-Inf
                            :upper-bound ##Inf
                            :mean mu
                            :variance (m/sq sd)
                            :fit-spec int-normal-fit-spec}))))

(t/use-fixtures :once
  (fn [run-tests]
    (.addMethod ^clojure.lang.MultiFn r/distribution :fit-test-int-normal int-normal)
    (try (run-tests)
         (finally (remove-method r/distribution :fit-test-int-normal)))))

(def ^:private gamma-sample
  (r/->seq (r/distribution :gamma {:shape 2.5 :scale 1.7 :rng (r/rng :jdk 3)}) 400))

(defn- error-data
  [f]
  (try (f) nil
       (catch clojure.lang.ExceptionInfo e (ex-data e))))

(t/deftest fit-errors-test
  (t/testing "distributions which can't be fitted"
    (t/is (= :not-fittable (:type (error-data #(sut/fit :constant [1.0 2.0])))))
    (t/is (= :not-fittable (:type (error-data #(sut/fit :dirichlet [1.0 2.0 3.0]))))))
  (t/testing "data"
    (t/is (= :invalid-input (:type (error-data #(sut/fit :gamma [1.0 -2.0 3.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :gamma [1.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :normal [1.0 ##NaN 2.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :beta [0.2 1.0 0.5]))))))
  (t/testing "options"
    (t/is (= :method (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:method :ml})))))
    (t/is (= :fixed (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:fixed {:nu 1.0}})))))
    (t/is (= :fixed (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:fixed {:sd -1.0}})))))
    (t/is (= :fixed (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:fixed {:mu "a"}})))))
    (t/is (= :fixed (:property (error-data #(sut/fit :normal [1.0 2.0 3.0] {:fixed {:mu 1.0 :sd 1.0}}))))))
  (t/testing "constant data have no normal distribution"
    (t/is (= :not-converged (:type (error-data #(sut/fit :normal [2.0 2.0 2.0])))))))

(t/deftest fit-mle-reference-test
  ;; closed form results (normal, log-normal, exponential) are compared to R to 1e-7: R fits the exponential
  ;; numerically (observed 7.8e-9); numeric results to 1e-3 on parameters (observed 5.2e-4 for cauchy, a flat
  ;; likelihood, otherwise 7.3e-5), 1e-7 on the information criteria (observed 4.2e-9) and 5e-3 on the
  ;; goodness-of-fit statistics (observed 2.8e-3), which follow the parameters
  (doseq [{:keys [distribution params data] :as c} @mle-reference
          closed-form? [true false]
          :let [res (sut/fit distribution data {:closed-form? closed-form?})
                exact? (and closed-form? (= :closed-form (:tier res)))
                ptol (if exact? 1.0e-7 1.0e-3)
                gtol (if exact? 1.0e-7 5.0e-3)]]
    (t/is (= distribution (r/distribution-id (:distribution res))) (str distribution))
    (t/is (:converged? res) (str distribution))
    (doseq [[nm v] params]
      (t/is (close? (get (:params res) nm) v ptol) (str distribution " " nm)))
    (doseq [k [:loglik :aic :aicc :bic]]
      (t/is (close? (get-in res [:stats k]) (get c k) 1.0e-7) (str distribution " " k)))
    (doseq [k [:ks :cvm :ad]]
      (t/is (close? (get-in res [:stats k]) (get c k) gtol) (str distribution " " k)))
    (t/is (= (:k c) (get-in res [:stats :k])))
    (t/is (= (:n c) (get-in res [:stats :n])))))

(t/deftest fit-tiers-test
  ;; observed difference between the numeric and the closed form parameters: 1.5e-8 (exponential)
  (doseq [k [:normal :exponential :log-normal]
          :let [data (case k
                       :normal (map #(- % 4.0) gamma-sample)
                       gamma-sample)
                cf (sut/fit k data)
                nm (sut/fit k data {:closed-form? false})]]
    (t/is (= :closed-form (:tier cf)))
    (t/is (= 0 (:iterations cf)))
    (t/is (= :numeric (:tier nm)))
    (t/is (pos? (:iterations nm)))
    (doseq [[p v] (:params cf)]
      (t/is (close? (get (:params nm) p) v 1.0e-7) (str k " " p)))))

(t/deftest fit-fixed-test
  (let [data (map #(- % 4.0) gamma-sample)
        mu 0.5
        sd (m/sqrt (m// (reduce + (map #(m/sq (m/- % mu)) data)) (count data)))
        res (sut/fit :normal data {:fixed {:mu mu}})]
    (t/testing "a fixed parameter is not fitted"
      (t/is (= :numeric (:tier res)))
      (t/is (= {:mu mu} (:fixed res)))
      (t/is (= mu (get-in res [:params :mu])))
      (t/is (close? (get-in res [:params :sd]) sd 1.0e-6))
      (t/is (= 1 (get-in res [:stats :k]))))
    (t/testing "the fitted distribution uses the fixed value"
      (t/is (m/delta-eq mu (r/mean (:distribution res))))))
  (t/testing "an integer parameter has to be fixed, the specification needs no estimators"
    (let [data (map #(- % 4.0) gamma-sample)
          err (error-data #(sut/fit :fit-test-int-normal data))
          res (sut/fit :fit-test-int-normal data {:fixed {:k 3}})
          ref (sut/fit :normal data)]
      (t/is (= :invalid-input (:type err)))
      (t/is (= :fixed (:property err)))
      (t/is (re-find #":k" (ex-message (try (sut/fit :fit-test-int-normal data)
                                            (catch clojure.lang.ExceptionInfo e e)))))
      (t/is (= 3.0 (get-in res [:params :k])))
      (t/is (= 2 (get-in res [:stats :k])))
      (t/is (close? (get-in res [:params :mu]) (get-in ref [:params :mu]) 1.0e-5))
      (t/is (close? (get-in res [:params :sd]) (get-in ref [:params :sd]) 1.0e-5)))))

(t/deftest fit-result-test
  (let [res (sut/fit :gamma gamma-sample)]
    (t/testing "keys"
      (t/is (= #{:distribution :params :method :tier :converged? :iterations :fixed :stats} (set (keys res))))
      (t/is (= #{:k :n :loglik :aic :aicc :bic :ks :cvm :ad} (set (keys (:stats res)))))
      (t/is (= :mle (:method res)))
      (t/is (= {} (:fixed res)))
      (t/is (= :gamma (r/distribution-id (:distribution res)))))
    (t/testing "the distribution has the fitted parameters"
      (t/is (m/delta-eq (r/mean (:distribution res))
                        (* (get-in res [:params :shape]) (get-in res [:params :scale])))))
    (t/testing "information criteria"
      (let [{:keys [k n loglik aic aicc bic]} (:stats res)]
        (t/is (= 2 k))
        (t/is (= 400 n))
        (t/is (m/delta-eq aic (- (* 2.0 k) (* 2.0 loglik))))
        (t/is (m/delta-eq bic (- (* k (m/log n)) (* 2.0 loglik))))
        (t/is (m/delta-eq aicc (+ aic (/ (* 2.0 k (inc k)) (- n k 1)))))
        (t/is (m/delta-eq loglik (r/log-likelihood (:distribution res) gamma-sample)))))
    (t/testing "AICc is undefined for n = k + 1"
      (t/is (= ##Inf (get-in (sut/fit :normal [1.0 2.0 4.0]) [:stats :aicc]))))))

(t/deftest fit-determinism-test
  (let [a (sut/fit :gamma gamma-sample {:rng (r/rng :jdk 7)})
        b (sut/fit :gamma gamma-sample {:rng (r/rng :jdk 7)})
        c (sut/fit :gamma gamma-sample {:rng (r/rng :jdk 99) :restarts 5})
        d (sut/fit :gamma gamma-sample)]
    (t/testing "the same seeded generator gives the same fit"
      (t/is (= (:params a) (:params b)))
      (t/is (= (:stats a) (:stats b))))
    (t/testing "another generator, more restarts or no generator reach the same optimum"
      (t/is (close? (get-in c [:stats :loglik]) (get-in a [:stats :loglik]) 1.0e-7))
      (t/is (close? (get-in d [:stats :loglik]) (get-in a [:stats :loglik]) 1.0e-7)))))

(t/deftest objective-function-test
  (let [objective #'sut/objective-function
        xs [0.5 1.5 2.5]
        nll (fn [d _] (- (r/log-likelihood d xs)))]
    (t/testing "the value of the objective"
      (t/is (m/delta-eq (- (r/log-likelihood (r/normal {:mu 1.0 :sd 2.0}) xs))
                        ((objective :normal {} [:mu :sd] identity nll) [1.0 2.0]))))
    (t/testing "fixed parameters are added to the point"
      (t/is (m/delta-eq (- (r/log-likelihood (r/normal {:mu 1.0 :sd 2.0}) xs))
                        ((objective :normal {:mu 1.0} [:sd] identity nll) [2.0]))))
    (t/testing "a failing or not finite evaluation is an infinite objective value"
      (t/is (= ##Inf ((objective :normal {} [:mu :sd] identity nll) [1.0 -2.0])))
      (t/is (= ##Inf ((objective :no-such-distribution {} [:mu :sd] identity nll) [1.0 2.0])))
      (t/is (= ##Inf ((objective :gamma {} [:shape :scale] identity (fn [d _] (- (r/log-likelihood d [-1.0 2.0])))) [2.0 1.0])))
      (t/is (= ##Inf ((objective :normal {} [:mu :sd] identity (fn [_ _] ##NaN)) [1.0 2.0]))))))

;; reference: R fitdistrplus (mgedist, msedist, qmedist, mmedist) and lmomco / nleqslv for the L-moments, generated by
;; utils/fastmath/dev/generate_fit_methods_reference.R
(def ^:private methods-reference
  (delay (edn/read-string (slurp (io/resource "random/fit_methods_reference.edn")))))

(t/deftest fit-methods-reference-test
  ;; observed difference of the parameters (largest per method over normal, gamma and weibull):
  ;; :ks 7.8e-9, :lmme 1.4e-9, :mme 2.8e-9 (normal, gamma), :cvm 6.8e-6, :ad* 4.0e-5, :qme 1.3e-5, :mps 3.1e-4
  (doseq [{:keys [distribution data estimates probs]} @methods-reference
          [method expected] estimates
          :when (not (and (= :weibull distribution) (= :mme method))) ;; R's numerical moment matching, see below
          :let [res (sut/fit distribution data {:method method :quantiles probs})
                tolerance (case method
                            (:ks :lmme :mme) 1.0e-6
                            1.0e-3)]]
    (t/is (= method (:method res)))
    (t/is (:converged? res) (str distribution " " method))
    (doseq [[nm v] expected]
      (t/is (close? (get-in res [:params nm]) v tolerance) (str distribution " " method " " nm)))))

(t/deftest fit-moment-matching-test
  (t/testing "the moments of the fitted distribution are the moments of the sample"
    ;; the weibull moment equations have no closed form: R solves them numerically with an error of 2.6e-4
    (let [{:keys [data]} (nth @methods-reference 2)
          n (count data)
          mean (/ (reduce + data) n)
          variance (/ (reduce + (map #(m/sq (- % mean)) data)) n)
          d (:distribution (sut/fit :weibull data {:method :mme}))]
      (t/is (close? (r/mean d) mean 1.0e-6))
      (t/is (close? (r/variance d) variance 1.0e-6))))
  (t/testing "the L-moments of the fitted distribution are the L-moments of the sample"
    (let [{:keys [data]} (nth @methods-reference 1)
          d (:distribution (sut/fit :gamma data {:method :lmme}))
          l-moments #'sut/l-moments]
      (t/is (close? (first (l-moments d 2)) (stats/l-moment data 1) 1.0e-6))
      (t/is (close? (second (l-moments d 2)) (stats/l-moment data 2) 1.0e-6))))
  (t/testing "the moments of a distribution which has none are undefined"
    (let [data (r/->seq (r/cauchy {:rng (r/rng :jdk 5)}) 200)]
      (t/is (= :moments-undefined (:type (error-data #(sut/fit :cauchy data {:method :mme})))))
      (t/is (= :moments-undefined (:type (error-data #(sut/fit :cauchy data {:method :lmme})))))))
  (t/testing "the moments of the specification are used"
    (let [data (map #(- % 4.0) gamma-sample)
          ref (sut/fit :normal data)]
      (reset! hook-calls {:moments 0 :lmoments 0})
      (let [mme (sut/fit :fit-test-int-normal data {:method :mme :fixed {:k 1}})]
        (t/is (pos? (:moments @hook-calls)))
        (t/is (zero? (:lmoments @hook-calls)))
        (t/is (close? (get-in mme [:params :mu]) (get-in ref [:params :mu]) 1.0e-6))
        (t/is (close? (get-in mme [:params :sd]) (get-in ref [:params :sd]) 1.0e-6)))
      (let [lmme (sut/fit :fit-test-int-normal data {:method :lmme :fixed {:k 1}})]
        (t/is (pos? (:lmoments @hook-calls)))
        (t/is (close? (get-in lmme [:params :sd]) (* (stats/l-moment data 2) (Math/sqrt Math/PI)) 1.0e-6)))))
  (t/testing "moments of a higher order and L-moments by integration"
    (let [d (r/gamma {:shape 2.5 :scale 1.7})
          raw (#'sut/raw-moments d 4)
          shape 2.5
          scale 1.7]
      (t/is (close? (nth raw 0) (* shape scale) 1.0e-8))
      (t/is (close? (nth raw 1) (* shape (inc shape) scale scale) 1.0e-8))
      (t/is (close? (nth raw 2) (* shape (inc shape) (+ shape 2) (Math/pow scale 3)) 1.0e-6))
      (t/is (close? (nth raw 3) (* shape (inc shape) (+ shape 2) (+ shape 3) (Math/pow scale 4)) 1.0e-6)))
    (let [e (r/exponential {:mean 2.0})
          [l1 l2 l3 l4] (#'sut/l-moments e 4)]
      ;; exponential: lambda_r = mean / (r (r - 1)), lambda_1 = mean
      (t/is (close? l1 2.0 1.0e-7))
      (t/is (close? l2 1.0 1.0e-7))
      (t/is (close? l3 (/ 2.0 6.0) 1.0e-7))
      (t/is (close? l4 (/ 2.0 12.0) 1.0e-7)))))

(t/deftest fit-options-test
  (t/testing "quantile matching"
    (let [data gamma-sample
          by-list (sut/fit :gamma data {:method :qme :quantiles [0.1 0.3 0.5 0.7 0.9]})
          by-count (sut/fit :gamma data {:method :qme :quantiles 5})
          by-strategy (sut/fit :gamma data {:method :qme :quantiles [0.1 0.3 0.5 0.7 0.9] :strategy :r1})]
      (t/is (:converged? by-list))
      (t/is (close? (get-in by-list [:params :shape]) 2.5 0.3))
      ;; five quantiles spread evenly from 0.01 to 0.99
      (t/is (not= (:params by-list) (:params by-count)))
      (t/is (not= (:params by-list) (:params by-strategy))))
    (t/is (= :quantiles (:property (error-data #(sut/fit :gamma gamma-sample {:method :qme :quantiles [0.5 1.5]})))))
    (t/is (= :quantiles (:property (error-data #(sut/fit :gamma gamma-sample {:method :qme :quantiles [0.5]})))))
    (t/is (= :quantiles (:property (error-data #(sut/fit :gamma gamma-sample {:method :qme :quantiles []}))))))
  (t/testing "optimizers"
    (let [lbfgsb (sut/fit :gamma gamma-sample {:method :cvm :optimizer :lbfgsb})
          simplex (sut/fit :gamma gamma-sample {:method :cvm :optimizer :nelder-mead})]
      (t/is (close? (get-in lbfgsb [:params :shape]) (get-in simplex [:params :shape]) 1.0e-3)))
    (t/is (= :optimizer (:property (error-data #(sut/fit :gamma gamma-sample {:optimizer :cmaes}))))))
  (t/testing "unknown method"
    (t/is (= :method (:property (error-data #(sut/fit :gamma gamma-sample {:method :ml}))))))
  (t/testing "fixed parameters with other methods"
    (doseq [method [:cvm :ks :ad :mps :qme :mme :lmme]
            :let [res (sut/fit :gamma gamma-sample {:method method :fixed {:shape 2.5}})]]
      (t/is (= 2.5 (get-in res [:params :shape])) (str method))
      (t/is (= 1 (get-in res [:stats :k])) (str method))
      (t/is (close? (get-in res [:params :scale]) 1.7 0.15) (str method))))
  (t/testing "ties in the sample"
    (let [data (map #(/ (Math/round (* 10.0 %)) 10.0) (map inc gamma-sample))
          res (sut/fit :gamma data {:method :mps})]
      (t/is (< (count (distinct data)) (count data)))
      (t/is (every? m/valid-double? (vals (:params res)))))))

;; metadata batch A

;; reference: R fitdistrplus::fitdist (stats, statmod, actuar, extraDistr, VGAM densities) and mmedist (beta), generated by
;; utils/fastmath/dev/generate_fit_batch_a_reference.R
(def ^:private batch-a-reference
  (delay (edn/read-string (slurp (io/resource "random/fit_batch_a_reference.edn")))))

(t/deftest fit-batch-a-reference-test
  ;; observed difference of the parameters: t 1.4e-3 (flat likelihood, R's simplex), f 2.1e-4, inverse Gaussian 8.2e-5
  ;; (R's numerical fit; the estimate here is a closed form), inverse gamma 7.3e-5, nakagami 6.2e-5, others below 3e-6;
  ;; log likelihood 2.1e-8 at most
  (doseq [{:keys [distribution method fixed params data loglik]} @batch-a-reference
          :let [res (sut/fit distribution data {:method method :fixed fixed})]]
    (t/is (:converged? res) (str distribution))
    (doseq [[nm v] params]
      (t/is (close? (get-in res [:params nm]) v 5.0e-3) (str distribution " " nm)))
    (when loglik
      (t/is (close? (get-in res [:stats :loglik]) loglik 1.0e-7) (str distribution)))))

(t/deftest fit-batch-a-recovery-test
  ;; the estimate maximizes the likelihood (it is not below the likelihood of the true parameters) and is close to
  ;; them; observed largest relative differences with 5000 observations: 5.8% (t), 4.5% (rayleigh location), 3.4%
  (doseq [[dist-key params fixed]
          [[:normal {:mu 1.5 :sd 2.0} {}]
           [:log-normal {:scale 0.5 :shape 0.8} {}]
           [:gamma {:shape 2.5 :scale 1.7} {}]
           [:beta {:alpha 2.0 :beta 5.0} {}]
           [:weibull {:alpha 1.8 :beta 3.0} {}]
           [:exponential {:mean 2.0} {}]
           [:uniform-real {:lower -1.0 :upper 3.0} {}]
           [:chi-squared {:degrees-of-freedom 4.0} {}]
           [:erlang {:k 3 :lambda 0.8} {:k 3}]
           [:rayleigh {:a 0.5 :beta 2.0} {}]
           [:inverse-gamma {:alpha 3.0 :beta 2.0} {}]
           [:inverse-gaussian {:mu 2.0 :lambda 3.0} {}]
           [:half-normal {:mu 0.5 :sigma 1.5} {}]
           [:nakagami {:mu 1.5 :omega 2.0} {}]
           [:f {:numerator-degrees-of-freedom 5.0 :denominator-degrees-of-freedom 12.0} {}]
           [:t {:degrees-of-freedom 6.0} {}]
           [:cauchy {:median -1.0 :scale 2.0} {}]]
          :let [data (r/->seq (r/distribution dist-key (assoc params :rng (r/rng :jdk 11))) 5000)
                res (sut/fit dist-key data {:fixed fixed})
                true-loglik (r/log-likelihood (r/distribution dist-key params) data)]]
    (t/is (:converged? res) (str dist-key))
    (t/is (<= true-loglik (+ (get-in res [:stats :loglik]) 1.0e-6)) (str dist-key))
    (doseq [[nm v] params]
      (t/is (close? (get-in res [:params nm]) v 0.1) (str dist-key " " nm)))))

(t/deftest fit-batch-a-closed-form-test
  (t/testing "uniform: the sample range"
    (let [data [0.3 -1.5 2.2 0.9 1.7]
          res (sut/fit :uniform-real data)]
      (t/is (= :closed-form (:tier res)))
      (t/is (= {:lower -1.5 :upper 2.2} (:params res)))
      (t/is (m/delta-eq (* -5 (m/log 3.7)) (get-in res [:stats :loglik])))))
  (t/testing "the sample has no estimate: constant data"
    ;; a constant sample has no closed form estimate (the support would have no length)
    (t/is (not= :closed-form (:tier (sut/fit :uniform-real [1.0 1.0 1.0])))))
  (t/testing "half-normal: the lower bound is the sample minimum and nothing around it has a larger likelihood"
    (let [data (r/->seq (r/half-normal {:mu 0.5 :sigma 1.5 :rng (r/rng :jdk 4)}) 300)
          res (sut/fit :half-normal data)
          {:keys [mu sigma]} (:params res)
          ll (fn [m s] (r/log-likelihood (r/half-normal {:mu m :sigma s}) data))]
      (t/is (= :closed-form (:tier res)))
      (t/is (= (apply min data) mu))
      (doseq [dm [-1.0e-3 -1.0e-6 0.0] ds [-1.0e-3 0.0 1.0e-3] :when (not (and (zero? dm) (zero? ds)))]
        (t/is (> (get-in res [:stats :loglik]) (ll (+ mu dm) (+ sigma ds)))))))
  (t/testing "moment and L-moment estimates with a closed form"
    (let [{:keys [data estimates]} (nth @methods-reference 1)
          gamma-mme (sut/fit :gamma data {:method :mme})
          {weibull-data :data} (nth @methods-reference 2)
          weibull-lmme (sut/fit :weibull weibull-data {:method :lmme})]
      (t/is (= :closed-form (:tier gamma-mme)))
      (t/is (= :closed-form (:tier weibull-lmme)))
      (t/is (= :numeric (:tier (sut/fit :gamma data {:method :mme :closed-form? false}))))
      (doseq [[nm v] (:mme estimates)]
        (t/is (close? (get-in gamma-mme [:params nm]) v 1.0e-8)))
      (doseq [[nm v] (:lmme (:estimates (nth @methods-reference 2)))]
        (t/is (close? (get-in weibull-lmme [:params nm]) v 1.0e-8))))
    (let [{:keys [data params]} (last @batch-a-reference)
          res (sut/fit :beta data {:method :mme})]
      (t/is (= :closed-form (:tier res)))
      (doseq [[nm v] params]
        (t/is (close? (get-in res [:params nm]) v 1.0e-8))))))

(t/deftest fit-batch-a-requirements-test
  (t/testing "the integer shape of the Erlang distribution has to be fixed"
    (t/is (= :fixed (:property (error-data #(sut/fit :erlang [1.0 2.0 3.0]))))))
  (t/testing "the chi distribution has only an integer parameter: it is searched, fixing it leaves nothing to fit"
    (let [data (r/->seq (r/chi {:nu 5 :rng (r/rng :jdk 3)}) 1000)
          res (sut/fit :chi data)
          loglik (fn [n] (r/log-likelihood (r/chi {:nu n}) data))
          fixed-error (error-data #(sut/fit :chi data {:fixed {:nu 5}}))]
      (t/is (= (double (apply max-key loglik (range 1 20))) (get-in res [:params :nu])))
      (t/is (>= (get-in res [:stats :loglik]) (loglik 5)))
      (t/is (= 1 (get-in res [:stats :k])))
      (t/is (= :fixed (:property fixed-error)))))
  (t/testing "data checks"
    (t/is (= :invalid-input (:type (error-data #(sut/fit :f [1.0 -2.0 3.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :nakagami [0.0 2.0 3.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :t [1.0 2.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :exponential [-1.0 2.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :beta [0.5 1.0 0.2])))))))

;; metadata batch B, discrete distributions

;; reference: R fitdistrplus::fitdist (stats, extraDistr, gamlss.dist), an optimized log likelihood for zipf, generated by
;; utils/fastmath/dev/generate_fit_batch_b_reference.R
(def ^:private batch-b-reference
  (delay (edn/read-string (slurp (io/resource "random/fit_batch_b_reference.edn")))))

(t/deftest fit-batch-b-reference-test
  ;; observed difference of the parameters: nbii 4.1e-4, negative binomial 2.4e-4 (R's numerical fit), beta-binomial and
  ;; bb 1.3e-4, nbi 8.0e-5, the others below 5e-7; log likelihood 7.8e-9 at most
  (doseq [{:keys [distribution fixed params data loglik]} @batch-b-reference
          :let [res (sut/fit distribution data {:fixed fixed})]]
    (t/is (:converged? res) (str distribution))
    (doseq [[nm v] params]
      (t/is (close? (get-in res [:params nm]) v 2.0e-3) (str distribution " " nm)))
    (t/is (close? (get-in res [:stats :loglik]) loglik 1.0e-7) (str distribution))
    (t/testing "the goodness-of-fit statistics are for continuous distributions only"
      (t/is (not-any? #(contains? (:stats res) %) [:ks :cvm :ad])))))

(t/deftest fit-integer-search-test
  (t/testing "the trials of the binomial distribution"
    ;; the maximum likelihood estimate of the trials is far from exact (the likelihood is flat, 28 for 25 true trials), so
    ;; the search is checked against an exhaustive search and against the likelihood of the true trials; the information
    ;; criteria count the trials as a fitted parameter
    (doseq [trials [10 25 50]
            :let [data (r/->seq (r/binomial {:trials trials :p 0.3 :rng (r/rng :jdk (+ 100 trials))}) 1000)
                  res (sut/fit :binomial data)
                  loglik (fn [n] (get-in (sut/fit :binomial data {:fixed {:trials n}}) [:stats :loglik]))
                  exhaustive (apply max-key loglik (range (apply max data) (* 3 trials)))]]
      (t/is (= (double exhaustive) (get-in res [:params :trials])) (str trials))
      (t/is (>= (get-in res [:stats :loglik]) (loglik trials)) (str trials))
      (t/is (close? (get-in res [:params :trials]) trials 0.25) (str trials))
      (t/is (= 2 (get-in res [:stats :k])))
      (t/is (= 1 (get-in (sut/fit :binomial data {:fixed {:trials trials}}) [:stats :k])))
      (t/is (= {} (:fixed res)))))
  (t/testing "the successes of the Pascal distribution"
    (doseq [r [2 4 7]
            :let [data (r/->seq (r/pascal {:r r :p 0.4 :rng (r/rng :jdk (+ 200 r))}) 1500)
                  res (sut/fit :pascal data)
                  loglik (fn [n] (get-in (sut/fit :pascal data {:fixed {:r n}}) [:stats :loglik]))
                  exhaustive (apply max-key loglik (range 1 (* 4 r)))]]
      (t/is (= (double exhaustive) (get-in res [:params :r])) (str r))
      (t/is (>= (get-in res [:stats :loglik]) (loglik r)) (str r))))
  (t/testing "other methods and the sample which has no finite maximum"
    (let [data (r/->seq (r/binomial {:trials 20 :p 0.4 :rng (r/rng :jdk 7)}) 1000)]
      (doseq [method [:mps :qme :cvm]]
        (t/is (close? (get-in (sut/fit :binomial data {:method method}) [:params :trials]) 20 0.25) (str method))))
    ;; over-dispersed counts: the likelihood grows with the trials up to the Poisson limit, the search stops at the limit
    (let [data (r/->seq (r/negative-binomial {:r 2.0 :p 0.3 :rng (r/rng :jdk 8)}) 500)]
      (t/is (= 1000000.0 (get-in (sut/fit :binomial data) [:params :trials])))))
  (t/testing "the number of elements of the Zipf distribution is the largest observation"
    (let [data (r/->seq (r/zipf {:number-of-elements 30 :exponent 1.5 :rng (r/rng :jdk 9)}) 500)
          res (sut/fit :zipf data)
          fixed (sut/fit :zipf data {:fixed {:number-of-elements (apply max data)}})]
      (t/is (= (double (apply max data)) (get-in res [:params :number-of-elements])))
      (t/is (close? (get-in res [:params :exponent]) (get-in fixed [:params :exponent]) 1.0e-6))))
  (t/testing "the discrete uniform distribution"
    (let [data [4 9 7 5 11 6 4]]
      (t/is (= {:lower 4.0 :upper 11.0} (:params (sut/fit :uniform-int data))))
      (t/is (= :closed-form (:tier (sut/fit :uniform-int data))))
      (t/is (= {:lower 0.0 :upper 11.0} (:params (sut/fit :uniform-int data {:fixed {:lower 0}}))))))
  (t/testing "integer parameters without a range have to be fixed"
    (t/is (= :fixed (:property (error-data #(sut/fit :beta-binomial [1 2 3 4])))))
    (t/is (= :fixed (:property (error-data #(sut/fit :bb [1 2 3 4])))))
    (t/is (= :fixed (:property (error-data #(sut/fit :uniform-int [1 2 3 4] {:closed-form? false}))))))
  (t/testing "a distribution with three integer parameters has no specification"
    (t/is (nil? (r/fit-spec :hypergeometric)))))

(t/deftest search-integer-test
  (let [search #'sut/search-integer
        parabola (fn [centre] (fn [i] (* (- i centre) (- i centre))))
        evaluations (atom 0)
        counted (fn [f] (fn [i] (swap! evaluations inc) (f i)))]
    (t/testing "the minimum is found from any start"
      (doseq [centre [1 2 7 40 999]
              start [1 3 40 500 1000]]
        (t/is (= centre (search (parabola centre) 1 1000 start)) (str centre " from " start))))
    (t/testing "the minimum at the bounds"
      (t/is (= 1 (search (fn [i] i) 1 1000 500)))
      (t/is (= 1000 (search (fn [i] (- i)) 1 1000 500)))
      (t/is (= 5 (search (fn [i] i) 5 5 5))))
    (t/testing "a start outside of the range is moved inside"
      (t/is (= 10 (search (parabola 10) 1 100 100000))))
    (t/testing "a plateau, infinite values outside"
      (t/is (= 50 (search (fn [i] (if (< i 3) ##Inf 1.0)) 1 100 50)))
      (t/is (<= 3 (search (fn [i] (if (< i 3) ##Inf 1.0)) 1 100 2)))
      (t/is (= 20 (search (fn [i] (if (< i 20) ##Inf (- i 20))) 1 1000000 5000))))
    (t/testing "a few evaluations for a wide range"
      (reset! evaluations 0)
      (t/is (= 123456 (search (counted (parabola 123456)) 1 1000000 1)))
      (t/is (< @evaluations 100)))))

(t/deftest fit-discrete-methods-test
  ;; the distance methods (:cvm, :qme) are far from the maximum likelihood estimate for discrete data (for the logarithmic
  ;; distribution 0.89 and 0.48 for 0.70): they only have to run; the spacings and the moments are close to it
  (t/testing "the methods run on discrete data and give a result close to the maximum likelihood estimate"
    (doseq [[dist-key params fixed]
            [[:poisson {:p 4.0} {}]
             [:geometric {:p 0.25} {}]
             [:negative-binomial {:r 3.5 :p 0.4} {}]
             [:nbi {:mu 3.0 :sigma 0.5} {}]
             [:nbii {:mu 3.0 :sigma 1.5} {}]
             [:binomial {:trials 20 :p 0.4} {:trials 20}]
             [:logarithmic {:p 0.7} {}]]
            :let [data (r/->seq (r/distribution dist-key (assoc params :rng (r/rng :jdk 21))) 2000)
                  mle (sut/fit dist-key data {:fixed fixed})]
            method [:cvm :mps :qme :mme]
            :let [res (sut/fit dist-key data {:method method :fixed fixed})]]
      (t/is (:converged? res) (str dist-key " " method))
      (doseq [[nm v] (:params mle)]
        (t/is (m/valid-double? (get-in res [:params nm])) (str dist-key " " method " " nm))
        (when (#{:mps :mme} method)
          (t/is (close? (get-in res [:params nm]) v 0.2) (str dist-key " " method " " nm))))))
  (t/testing "ties of the maximum product of spacings use the mass of the observation: for a Poisson sample the estimate is near the mean"
    (let [data (r/->seq (r/poisson {:p 6.0 :rng (r/rng :jdk 22)}) 3000)]
      (t/is (close? (get-in (sut/fit :poisson data {:method :mps}) [:params :p]) (/ (reduce + data) (count data)) 0.03))))
  (t/testing "data checks"
    (t/is (= :invalid-input (:type (error-data #(sut/fit :poisson [1.5 2.0 3.0])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :poisson [-1 2 3])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :logarithmic [0 1 2])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :zipf [0 1 2])))))
    (t/is (= :invalid-input (:type (error-data #(sut/fit :negative-binomial [3])))))))

(t/deftest fit-bernoulli-test
  ;; a binomial distribution with one trial: the trials are fixed at 1
  (let [data (r/->seq (r/bernoulli {:p 0.35 :rng (r/rng :jdk 23)}) 1000)
        res (sut/fit :bernoulli data {:fixed {:trials 1}})]
    (t/is (= :closed-form (:tier res)))
    (t/is (m/delta-eq (/ (reduce + data) 1000.0) (get-in res [:params :p])))))

;; metadata batch C, heavy-tailed, location-scale and bounded distributions

;; reference: R fitdistrplus::fitdist (stats, extraDistr, actuar, VGAM, gamlss.dist), circular::mle.vonmises and optimized
;; log likelihoods, generated by utils/fastmath/dev/generate_fit_batch_c_reference.R
(def ^:private batch-c-reference
  (delay (edn/read-string (slurp (io/resource "random/fit_batch_c_reference.edn")))))

(t/deftest fit-batch-c-reference-test
  ;; observed difference of the parameters: laplace 5.3e-3 (R's numerical fit, the estimate here is a closed form), von
  ;; Mises 3.6e-3 (R's concentration is an approximation, the log likelihood here is higher), others below 8e-4; the log
  ;; likelihood is never lower than R's, the largest difference is 3.3e-6 (relative)
  (doseq [{:keys [distribution fixed params data loglik]} @batch-c-reference
          :let [res (sut/fit distribution data {:fixed fixed :rng (r/rng :jdk 5)})]]
    (t/is (:converged? res) (str distribution))
    (doseq [[nm v] params]
      (t/is (close? (get-in res [:params nm]) v 1.0e-2) (str distribution " " nm)))
    (t/is (>= (get-in res [:stats :loglik]) (- loglik (* 1.0e-7 (m/abs loglik)))) (str distribution))
    (t/is (close? (get-in res [:stats :loglik]) loglik 1.0e-5) (str distribution))))

(t/deftest fit-batch-c-recovery-test
  ;; the estimate maximizes the likelihood (it is not below the likelihood of the true parameters) and is close to them;
  ;; observed largest relative differences with 3000 observations: 5.6% (Johnson SB), 4.2% (Frechet), 3.6% (Johnson SU)
  (doseq [[dist-key params fixed]
          [[:cauchy {:median -1.0 :scale 2.0} {}]
           [:laplace {:mu 1.0 :beta 2.0} {}]
           [:logistic {:mu 1.0 :s 2.0} {}]
           [:gumbel {:mu 1.0 :beta 2.0} {}]
           [:levy {:mu 0.5 :c 2.0} {}]
           [:pareto {:scale 1.5 :shape 3.0} {}]
           [:frechet {:alpha 3.0 :beta 2.0 :delta 0.5} {}]
           [:log-logistic {:alpha 3.0 :beta 2.0} {}]
           [:triangular {:a -1.0 :c 0.5 :b 3.0} {}]
           [:power {:a 0.5 :b 3.0 :c 2.0} {}]
           [:reciprocal {:a 1.0 :b 10.0} {}]
           [:johnson-su {:gamma 0.5 :delta 1.5 :xi 1.0 :lambda 2.0} {}]
           [:johnson-sb {:gamma 0.5 :delta 1.5 :xi 1.0 :lambda 4.0} {}]
           [:johnson-sl {:gamma 0.5 :delta 1.5 :xi 1.0 :lambda 1.0} {:lambda 1.0}]
           [:fatigue-life {:alpha 0.5 :beta 2.0 :gamma 0.7} {}]
           [:hyperbolic-secant {:mu 1.0 :sigma 2.0} {}]
           [:half-cauchy {:mu 0.5 :scale 2.0} {}]
           [:half-logistic {:scale 2.0} {}]
           [:folded-normal {:mu 1.5 :sigma 1.0} {}]
           [:beta-symmetrical {:alpha 3.0} {}]
           [:von-mises {:mu 0.5 :kappa 2.0} {}]
           [:ex-gaussian {:mu 1.0 :sigma 0.5 :tau 1.0} {}]
           [:exgaus {:mu 1.0 :sigma 0.5 :nu 1.0} {}]
           [:pearson-6 {:alpha1 3.0 :alpha2 5.0 :beta 2.0} {}]]
          :let [data (r/->seq (r/distribution dist-key (assoc params :rng (r/rng :jdk 11))) 3000)
                res (sut/fit dist-key data {:fixed fixed :rng (r/rng :jdk 5)})
                true-loglik (r/log-likelihood (r/distribution dist-key params) data)]]
    (t/is (:converged? res) (str dist-key))
    (t/is (<= true-loglik (+ (get-in res [:stats :loglik]) 1.0e-6)) (str dist-key))
    (doseq [[nm v] (apply dissoc params (keys fixed))]
      (t/is (close? (get-in res [:params nm]) v 0.15) (str dist-key " " nm)))))

(t/deftest fit-support-test
  (t/testing "the ends of the support are searched outside of the sample, the whole sample stays inside"
    (doseq [[dist-key params lower upper]
            [[:triangular {:a -1.0 :c 0.5 :b 3.0} :a :b]
             [:power {:a 0.5 :b 3.0 :c 2.0} :a :b]
             [:reciprocal {:a 1.0 :b 10.0} :a :b]
             [:pareto {:scale 1.5 :shape 3.0} :scale nil]
             [:levy {:mu 0.5 :c 2.0} :mu nil]
             [:frechet {:alpha 3.0 :beta 2.0 :delta 0.5} :delta nil]
             [:fatigue-life {:alpha 0.5 :beta 2.0 :gamma 0.7} :alpha nil]
             [:half-cauchy {:mu 0.5 :scale 2.0} :mu nil]
             [:johnson-sb {:gamma 0.5 :delta 1.5 :xi 1.0 :lambda 4.0} :xi nil]]
            seed [1 2 3]
            :let [data (r/->seq (r/distribution dist-key (assoc params :rng (r/rng :jdk (+ 300 seed)))) 500)
                  res (sut/fit dist-key data {:rng (r/rng :jdk seed)})]]
      (t/is (<= (get-in res [:params lower]) (apply min data)) (str dist-key " " seed))
      (when upper
        (t/is (>= (get-in res [:params upper]) (apply max data)) (str dist-key " " seed)))
      (t/is (m/valid-double? (get-in res [:stats :loglik])) (str dist-key " " seed))))
  (t/testing "closed forms: Pareto and reciprocal estimates are the sample extremes"
    (let [data [2.5 1.7 4.2 3.3 1.9 6.0]
          pareto (sut/fit :pareto data)
          reciprocal (sut/fit :reciprocal data)]
      (t/is (= :closed-form (:tier pareto)))
      (t/is (= 1.7 (get-in pareto [:params :scale])))
      (t/is (m/delta-eq (/ 6.0 (reduce + (map #(Math/log (/ % 1.7)) data))) (get-in pareto [:params :shape])))
      (t/is (= {:a 1.7 :b 6.0} (:params reciprocal)))
      (t/is (= :closed-form (:tier reciprocal)))))
  (t/testing "closed form of the Laplace distribution: the median and the mean absolute deviation"
    (let [data [1.0 2.0 4.0 7.0 8.0]
          res (sut/fit :laplace data)]
      (t/is (= :closed-form (:tier res)))
      (t/is (= 4.0 (get-in res [:params :mu])))
      (t/is (m/delta-eq (/ (+ 3 2 0 3 4) 5.0) (get-in res [:params :beta])))
      (t/is (= 3.0 (get-in (sut/fit :laplace [1.0 2.0 4.0 5.0]) [:params :mu])))))
  (t/testing "the angles of the von Mises distribution have to lie in an interval of the length 2 pi"
    (t/is (= :invalid-input (:type (error-data #(sut/fit :von-mises [-3.2 0.1 3.2])))))
    (t/is (nil? (error-data #(sut/fit :von-mises [-0.5 0.1 0.3 0.6 -0.2 0.0 0.2]))))))

(t/deftest fit-heavy-tails-test
  (t/testing "moments which don't exist"
    (let [cauchy (r/->seq (r/cauchy {:rng (r/rng :jdk 5)}) 300)
          levy (r/->seq (r/levy {:rng (r/rng :jdk 6)}) 300)
          pareto (r/->seq (r/pareto {:scale 1.0 :shape 1.5 :rng (r/rng :jdk 7)}) 1000)]
      (doseq [[dist-key data] [[:cauchy cauchy] [:levy levy]]
              method [:mme :lmme]]
        (t/is (= :moments-undefined (:type (error-data #(sut/fit dist-key data {:method method})))) (str dist-key " " method)))
      ;; the shape 1.5 has a mean but no variance: L-moments exist, the second raw moment does not
      (t/is (= :moments-undefined (:type (error-data #(sut/fit :pareto pareto {:method :mme})))))
      (t/is (:converged? (sut/fit :pareto pareto {:method :lmme})))
      (t/is (= :closed-form (:tier (sut/fit :pareto pareto))))))
  (t/testing "the methods which need no moments work"
    (let [cauchy (r/->seq (r/cauchy {:median 1.0 :scale 2.0 :rng (r/rng :jdk 5)}) 1000)
          levy (r/->seq (r/levy {:mu 0.5 :c 2.0 :rng (r/rng :jdk 6)}) 1000)]
      (doseq [method [:mle :qme :cvm :ad :mps]
              [dist-key data params] [[:cauchy cauchy {:median 1.0 :scale 2.0}] [:levy levy {:mu 0.5 :c 2.0}]]
              ;; the quantile matching with the quantiles of the far tails of a heavy tailed distribution is dominated by them
              :let [res (sut/fit dist-key data {:method method :quantiles [0.1 0.25 0.5 0.75 0.9]})]]
        (t/is (:converged? res) (str dist-key " " method))
        ;; the location of the Levy distribution is not identified by a few central quantiles
        (when (not= :qme method)
          (doseq [[nm v] params]
            (t/is (close? (get-in res [:params nm]) v 0.3) (str dist-key " " method " " nm))))))))
